// ── Seed ────────────────────────────────────────────────────────────────────

async function seed() {
  const slugToId = {}

  for (const page of PAGES) {
    const { data, error } = await supabase.from('pages').upsert(page, { onConflict: 'slug' }).select('id').single()
    if (error) { console.error('Page error:', page.slug, error.message); continue }
    slugToId[page.slug] = data.id
    console.log('  ✓ page:', page.slug)
  }

  const glossaryId = slugToId['ai-glossary']
  if (glossaryId) {
    await supabase.from('page_cards').delete().eq('page_id', glossaryId)
    const { error } = await supabase.from('page_cards').insert(GLOSSARY.map(c => ({ ...c, page_id: glossaryId })))
    if (error) console.error('Glossary error:', error.message)
    else console.log('  ✓ glossary:', GLOSSARY.length, 'terms')
  }

  for (const entry of ENTRIES) {
    const { topics, ...row } = entry
    const pageIds = topics.map(t => slugToId[t]).filter(Boolean)
    if (pageIds.length !== topics.length) { console.error('Unknown topic for entry:', entry.slug, topics); continue }
    const { data, error } = await supabase.from('entries')
      .upsert({ ...row, updated_at: row.published_at }, { onConflict: 'slug' })
      .select('id').single()
    if (error) { console.error('Entry error:', entry.slug, error.message); continue }
    await supabase.from('entry_topics').delete().eq('entry_id', data.id)
    const { error: tErr } = await supabase.from('entry_topics').insert(pageIds.map(page_id => ({ entry_id: data.id, page_id })))
    if (tErr) console.error('Entry topics error:', entry.slug, tErr.message)
    else console.log('  ✓ entry:', entry.slug, '→', topics.join(', '))
  }

  console.log('Done.')
}

seed()
